	b1 := uint64(y.B0.A1[0])
	b2 := uint64(y.B1.A0[0])
	b3 := uint64(y.B1.A1[0])
	b4 := uint64(y.B2.A0[0])
	b5 := uint64(y.B2.A1[0])

