	r = montReduceLazy(a0*b1+a1*b0) + montReduceLazy(a2*b4+a2*b5)
	r += montReduceLazy(a3*b4+a4*b2) + montReduceLazy(a4*b3+a5*b2)
	rA = montReduceLazy(a3*b5 + a5*b3)
	z.B0.A1[0] = reduceSmall(r + 3*rA)

